fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day abbreviation to its index relative to Sunday.
    // Sunday = 0, Monday = 1, ..., Saturday = 6.
    let day_idx = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => panic!("Invalid day abbreviation"),  // Given problem specification, input is always valid.
    };

    // The number of days to next Sunday:
    // If today is Sunday (0), the next Sunday is 7 days away.
    // Otherwise, subtract current index from 7.
    if day_idx == 0 {
        7
    } else {
        7 - day_idx
    }
}